import{_ as e,o as t,c as r,a6 as o}from"./chunks/framework.iHSbdEy0.js";const p=JSON.parse('{"title":"Metadata and CRS","description":"","frontmatter":{},"headers":[],"relativePath":"background/metadata-and-crs.md","filePath":"background/metadata-and-crs.md","lastUpdated":null}'),n={name:"background/metadata-and-crs.md"};function s(d,a,c,i,m,l){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="Metadata-and-CRS" tabindex="-1">Metadata and CRS <a class="header-anchor" href="#Metadata-and-CRS" aria-label="Permalink to &quot;Metadata and CRS {#Metadata-and-CRS}&quot;">​</a></h1><p>Spatial tables need two kinds of context: which columns contain geometries and which coordinate reference system (CRS) describes their coordinates. GeoDataFrames stores both as table metadata. That keeps an ordinary DataFrame interoperable while giving readers and writers a single source for spatial defaults.</p><p>Assigning a CRS records the meaning of coordinates already in a table. <code>setcrs!</code> changes that label only; it does not alter any coordinates. Use it when the coordinates already use a known CRS but the table lacks that information.</p><p>Transforming a CRS changes coordinate values to express the same locations in another system. <code>reproject</code> returns a transformed copy, and <code>reproject!</code> replaces the geometry coordinates in place. The source CRS must be correct before either transformation can be meaningful.</p><p>The <a href="./../reference/metadata">metadata reference</a> specifies the stored metadata and its accessors. Use <a href="./../how-to/manage-metadata">manage geometry metadata</a> to assign geometry metadata and <a href="./../how-to/reproject-data">reproject data</a> to transform coordinates.</p>',5)])])}const f=e(n,[["render",s]]);export{p as __pageData,f as default};
